turns[..recent_start]
        .iter()
        .enumerate()
        .map(|(turn_index, turn)| {
            let next_started_at = turns
                .get(turn_index + 1)
                .map(|next_turn| next_turn.started_at.as_str());
            (turn.started_at.as_str(), next_started_at)
        })
        .collect::<Vec<_>>

