        .map(|(offset, turn)| {
            let turn_index = recent_start + offset;
            let next_started_at = turns
                .get(turn_index + 1)
                .map(|next_turn| next_turn.started_at.clone());
            (turn.started_at.clone(), next_started_at)
        })
        .collect::<Vec<_>>
